'use strict';

const localeTags = {
  ko: 'ko-KR',
  en: 'en-US',
  ja: 'ja-JP',
  'zh-CN': 'zh-CN',
  es: 'es-ES',
  fr: 'fr-FR',
  de: 'de-DE',
  ru: 'ru-RU',
};
const localeIndex = Object.fromEntries(Object.keys(localeTags).map((locale, index) => [locale, index]));

function resolveLocale(tag) {
  const normalized = String(tag ?? '').trim().toLowerCase().replaceAll('_', '-');
  if (normalized === 'zh' || /^zh-(?:hans|cn|sg)(?:-|$)/.test(normalized)) return 'zh-CN';
  const primary = normalized.split('-', 1)[0];
  return Object.hasOwn(localeTags, primary) ? primary : null;
}

